1	-- 20260420000017_add_app_id_to_legacy_tables.sql
2	--
3	-- Adds app_id to all 34 legacy tables that were created before the BUBS
4	-- multi-app architecture. Backfills existing rows with the Rankora app UUID,
5	-- replaces weak/open RLS policies with proper is_account_member() +
6	-- has_app_access() checks matching the rankora_* table convention.
7	-- ============================================================================
8	
9	-- ────────────────────────────────────────────────────────────────────────────
10	-- PART 1: Add app_id column + backfill + NOT NULL
11	-- ────────────────────────────────────────────────────────────────────────────
12	
13	-- Helper: wrap repeated ALTER + UPDATE + SET NOT NULL in a DO block
14	-- so the migration is idempotent (safe to re-run if partially applied).
15	
16	DO $add_app_id$
17	DECLARE
18	  v_app_id uuid := get_app_id('rankora');
19	  tbl text;
20	BEGIN
21	  IF v_app_id IS NULL THEN
22	    RAISE EXCEPTION 'Rankora app not found in apps table — cannot backfill app_id';
23	  END IF;
24	
25	  -- ── Category 1: tables with account_id ──────────────────────────────────
26	  FOREACH tbl IN ARRAY ARRAY[
27	    'activity_log',
28	    'agency_clients',
29	    'agency_commissions',
30	    'agency_communications',
31	    'agency_contacts',
32	    'agency_invoices',
33	    'agency_mandates',
34	    'agency_placements',
35	    'availability_slots',
36	    'guest_links',
37	    'hire_outcomes',
38	    'interviews',
39	    'notifications',
40	    'outreach_history',
41	    'payments',
42	    'scorecard_responses',
43	    'scorecard_templates',
44	    'sequences',
45	    'stage_tracker',
46	    'talent_pool',
47	    'talent_pool_members',
48	    'team_invitations',
49	    'webhook_configs'
50	  ]
51	  LOOP
52	    IF NOT EXISTS (
53	      SELECT 1 FROM information_schema.columns
54	      WHERE table_schema = 'public' AND table_name = tbl AND column_name = 'app_id'
55	    ) THEN
56	      EXECUTE format('ALTER TABLE %I ADD COLUMN app_id uuid REFERENCES apps(id)', tbl);
57	      EXECUTE format('UPDATE %I SET app_id = $1 WHERE app_id IS NULL', tbl) USING v_app_id;
58	      EXECUTE format('ALTER TABLE %I ALTER COLUMN app_id SET NOT NULL', tbl);
59	    END IF;
60	  END LOOP;
61	
62	  -- ── Category 2: tables connected via FK chain ───────────────────────────
63	  FOREACH tbl IN ARRAY ARRAY[
64	    'booking_tokens',
65	    'candidate_stages',
66	    'career_subscribers',
67	    'job_form_fields',
68	    'job_views',
69	    'outreach_log',
70	    'sequence_enrollments',
71	    'sequence_steps',
72	    'stage_automations',
73	    'stage_history',
74	    'sms_logs'
75	  ]
76	  LOOP
77	    IF NOT EXISTS (
78	      SELECT 1 FROM information_schema.columns
79	      WHERE table_schema = 'public' AND table_name = tbl AND column_name = 'app_id'
80	    ) THEN
81	      EXECUTE format('ALTER TABLE %I ADD COLUMN app_id uuid REFERENCES apps(id)', tbl);
82	      EXECUTE format('UPDATE %I SET app_id = $1 WHERE app_id IS NULL', tbl) USING v_app_id;
83	      EXECUTE format('ALTER TABLE %I ALTER COLUMN app_id SET NOT NULL', tbl);
84	    END IF;
85	  END LOOP;
86	END $add_app_id$;
