1	-- 20260420000018_fix_app_id_defaults_and_triggers.sql
2	--
3	-- Fixes the INSERT failure on all 34 legacy tables from migration 0017.
4	-- Problem: app_id is NOT NULL but has no DEFAULT and no trigger — frontend
5	-- never passes app_id, so all INSERTs fail with "null value" constraint.
6	--
7	-- Solution:
8	-- 1. Add DEFAULT get_app_id('rankora') on app_id for all 34 tables
9	-- 2. Add BEFORE INSERT trigger as safety net (in case DEFAULT doesn't fire)
10	-- 3. Add app_id to the 2 remaining gap tables (rankora_platform_config,
11	--    email_ingest_logs)
12	-- ============================================================================
13	
14	
15	-- ────────────────────────────────────────────────────────────────────────────
16	-- PART 1: Shared trigger function — auto-populates app_id on INSERT
17	-- ────────────────────────────────────────────────────────────────────────────
18	
19	CREATE OR REPLACE FUNCTION set_rankora_app_id()
20	RETURNS trigger
21	LANGUAGE plpgsql AS $$
22	BEGIN
23	  IF NEW.app_id IS NULL THEN
24	    NEW.app_id := get_app_id('rankora');
25	  END IF;
26	  RETURN NEW;
27	END;
28	$$;
29	
30	
