178	-- rankora_platform_config (PK is account_id, no id column)
179	DO $$ BEGIN
180	  IF NOT EXISTS (
181	    SELECT 1 FROM information_schema.columns
182	    WHERE table_schema = 'public' AND table_name = 'rankora_platform_config' AND column_name = 'app_id'
