203	// ─── Mutations ───────────────────────────────────────────────────────────────
204	
205	export function useCreateSequence() {
206	  const { user } = useAuth();
207	  const queryClient = useQueryClient();
208	
209	  return useMutation({
210	    mutationFn: async (input: CreateSequenceInput): Promise<Sequence> => {
211	      const { data, error } = await (supabase as any)
212	        .from("sequences")
213	        .insert({ ...input, user_id: user!.id })
214	        .select()
215	        .single();
216	      if (error) throw error;
217	      return data;
218	    },
219	    onSuccess: () => {
220	      queryClient.invalidateQueries({ queryKey: qk.sequences() });
221	    },
222	  });
223	}
224	
225	export function useUpdateSequence() {
226	  const queryClient = useQueryClient();
227	
228	  return useMutation({
229	    mutationFn: async ({ id, ...updates }: UpdateSequenceInput): Promise<void> => {
230	      const { error } = await (supabase as any)
231	        .from("sequences")
232	        .update(updates)
233	        .eq("id", id);
234	      if (error) throw error;
235	    },
236	    onSuccess: (_data, variables) => {
237	      queryClient.invalidateQueries({ queryKey: qk.sequences() });
238	      queryClient.invalidateQueries({ queryKey: qk.sequence(variables.id) });
239	    },
240	  });
241	}
242	
243	export function useDeleteSequence() {
244	  const queryClient = useQueryClient();
245	
246	  return useMutation({
247	    mutationFn: async (id: string): Promise<void> => {
248	      const { error } = await (supabase as any)
249	        .from("sequences")
250	        .delete()
251	        .eq("id", id);
252	      if (error) throw error;
253	    },
254	    onSuccess: () => {
255	      queryClient.invalidateQueries({ queryKey: qk.sequences() });
256	    },
257	  });
258	}
