-- ============================================================================
-- 20260420000020_comprehensive_save_path_fixes.sql
--
-- Comprehensive residual save-path fixes after migrations 0017-0019.
-- Covers:
--   1.1  INSTEAD OF triggers for profiles view + admin_audit_logs view
--   1.2  candidate_stages schema mismatch (updated_at/updated_by/UNIQUE)
--   1.3  hire_outcomes schema mismatch (recommendation/updated_at/UNIQUE)
--   1.4  sequences BEFORE INSERT trigger for account_id resolution
--   1.5  Shared set_rankora_account_id() trigger on 17 legacy tables
--   1.6  outreach_log missing job_id column
--   1.7  guest_links missing label column
--   1.8  plans compat layer (dodo_product_id, dodo_credit_entitlement_id,
--          is_trial, price, credits, active, features columns + sync trigger)
-- ============================================================================


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.1a: INSTEAD OF UPDATE trigger on profiles view
-- Maps avatar_url/full_name → users, email_enabled → rankora_platform_config
-- Migration 0016 added profiles_update_trigger but only handled a subset.
-- We replace it here with the full set of columns.
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION profiles_full_update_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  -- Update user-level fields on the users table
  UPDATE users
  SET
    full_name  = COALESCE(NEW.full_name, full_name),
    avatar_url = COALESCE(NEW.avatar_url, avatar_url),
    updated_at = now()
  WHERE id = auth.uid();

  -- Update email_ingestion_enabled on rankora_platform_config for the account
  IF NEW.email_enabled IS DISTINCT FROM OLD.email_enabled THEN
    UPDATE rankora_platform_config
    SET email_ingestion_enabled = NEW.email_enabled
    WHERE account_id = COALESCE(OLD.account_id, get_primary_account(auth.uid()));
  END IF;

  RETURN NEW;
END;
$$;

-- Drop any existing profile update triggers installed by migration 0016
DROP TRIGGER IF EXISTS profiles_update_instead_of ON profiles;
DROP TRIGGER IF EXISTS profiles_full_update_instead_of ON profiles;

CREATE TRIGGER profiles_full_update_instead_of
  INSTEAD OF UPDATE ON profiles
  FOR EACH ROW EXECUTE FUNCTION profiles_full_update_trigger();

-- Ensure UPDATE permission on profiles view
GRANT UPDATE ON profiles TO authenticated;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.1b: INSTEAD OF INSERT trigger on admin_audit_logs view
-- Maps admin_user_id → user_id, details → changes_json
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION admin_audit_logs_insert_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  INSERT INTO audit_logs (
    account_id,
    app_id,
    user_id,
    action,
    entity_type,
    entity_id,
    changes_json,
    ip_address,
    user_agent
  ) VALUES (
    get_primary_account(COALESCE(NEW.admin_user_id, auth.uid())),
    get_app_id('rankora'),
    COALESCE(NEW.admin_user_id, NEW.user_id, auth.uid()),
    COALESCE(NEW.action, 'admin.action'),
    NEW.entity_type,
    NEW.entity_id,
    COALESCE(NEW.details, NEW.changes_json),
    NEW.ip_address,
    NEW.user_agent
  );
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS admin_audit_logs_insert_instead_of ON admin_audit_logs;
CREATE TRIGGER admin_audit_logs_insert_instead_of
  INSTEAD OF INSERT ON admin_audit_logs
  FOR EACH ROW EXECUTE FUNCTION admin_audit_logs_insert_trigger();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.2: candidate_stages — add updated_at, updated_by, UNIQUE constraint
-- Hook upserts with: updated_at, updated_by, resume_id, job_id, stage
-- Table has: moved_at, moved_by (kept for compat)
-- Trigger keeps moved_at↔updated_at and moved_by↔updated_by in sync
-- ────────────────────────────────────────────────────────────────────────────

ALTER TABLE candidate_stages
  ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now(),
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id);

-- Backfill from existing moved_at/moved_by where null
UPDATE candidate_stages SET updated_at = moved_at WHERE updated_at IS NULL;
UPDATE candidate_stages SET updated_by = moved_by WHERE updated_by IS NULL;

-- Add UNIQUE constraint (idempotent)
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'candidate_stages_resume_id_job_id_key'
      AND conrelid = 'candidate_stages'::regclass
  ) THEN
    -- Deduplicate first: keep the most recent row for each (resume_id, job_id)
    DELETE FROM candidate_stages cs
    WHERE id NOT IN (
      SELECT DISTINCT ON (resume_id, job_id) id
      FROM candidate_stages
      ORDER BY resume_id, job_id, moved_at DESC NULLS LAST
    );
    ALTER TABLE candidate_stages ADD CONSTRAINT candidate_stages_resume_id_job_id_key
      UNIQUE (resume_id, job_id);
  END IF;
END $$;

-- Sync trigger: keeps moved_at↔updated_at and moved_by↔updated_by in sync
CREATE OR REPLACE FUNCTION candidate_stages_sync_timestamps()
RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- Whichever column the caller set, mirror to the other alias
  IF NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
    NEW.moved_at := NEW.updated_at;
  ELSIF NEW.moved_at IS DISTINCT FROM OLD.moved_at THEN
    NEW.updated_at := NEW.moved_at;
  ELSE
    NEW.updated_at := now();
    NEW.moved_at   := now();
  END IF;

  IF NEW.updated_by IS DISTINCT FROM OLD.updated_by THEN
    NEW.moved_by := NEW.updated_by;
  ELSIF NEW.moved_by IS DISTINCT FROM OLD.moved_by THEN
    NEW.updated_by := NEW.moved_by;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS candidate_stages_sync_timestamps ON candidate_stages;
CREATE TRIGGER candidate_stages_sync_timestamps
  BEFORE INSERT OR UPDATE ON candidate_stages
  FOR EACH ROW EXECUTE FUNCTION candidate_stages_sync_timestamps();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.3: hire_outcomes — add recommendation, updated_at, UNIQUE constraint
-- Hook upserts with: recommendation, updated_at, onConflict: "resume_id,job_id"
-- ────────────────────────────────────────────────────────────────────────────

ALTER TABLE hire_outcomes
  ADD COLUMN IF NOT EXISTS recommendation text,
  ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();

-- Add UNIQUE constraint (idempotent)
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'hire_outcomes_resume_id_job_id_key'
      AND conrelid = 'hire_outcomes'::regclass
  ) THEN
    -- Deduplicate first: keep most recent per (resume_id, job_id)
    DELETE FROM hire_outcomes ho
    WHERE id NOT IN (
      SELECT DISTINCT ON (resume_id, job_id) id
      FROM hire_outcomes
      ORDER BY resume_id, job_id, created_at DESC NULLS LAST
    );
    ALTER TABLE hire_outcomes ADD CONSTRAINT hire_outcomes_resume_id_job_id_key
      UNIQUE (resume_id, job_id);
  END IF;
END $$;

-- Auto-update updated_at on row change
CREATE OR REPLACE FUNCTION hire_outcomes_set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS hire_outcomes_set_updated_at ON hire_outcomes;
CREATE TRIGGER hire_outcomes_set_updated_at
  BEFORE UPDATE ON hire_outcomes
  FOR EACH ROW EXECUTE FUNCTION hire_outcomes_set_updated_at();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.4: sequences — BEFORE INSERT trigger to resolve account_id
-- Safety net so frontend inserts without account_id still succeed
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION sequences_resolve_account_id()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.account_id IS NULL THEN
    NEW.account_id := COALESCE(
      NEW.account_id,
      get_primary_account(auth.uid())
    );
  END IF;
  -- Also map user_id → created_by if the caller passed user_id instead
  IF NEW.account_id IS NULL THEN
    RAISE EXCEPTION 'sequences: account_id could not be resolved for user %', auth.uid();
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS sequences_resolve_account_id ON sequences;
CREATE TRIGGER sequences_resolve_account_id
  BEFORE INSERT ON sequences
  FOR EACH ROW EXECUTE FUNCTION sequences_resolve_account_id();

-- Also add is_active column alias (frontend uses is_active, table has status)
ALTER TABLE sequences ADD COLUMN IF NOT EXISTS is_active boolean DEFAULT true;

-- Sync trigger: keep is_active ↔ status in sync
CREATE OR REPLACE FUNCTION sequences_sync_status()
RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
    NEW.status := CASE WHEN NEW.is_active THEN 'active' ELSE 'paused' END;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.is_active := (NEW.status = 'active');
  END IF;
  -- On insert, default both if neither set
  IF TG_OP = 'INSERT' THEN
    NEW.is_active := COALESCE(NEW.is_active, true);
    NEW.status    := COALESCE(NEW.status, CASE WHEN NEW.is_active THEN 'active' ELSE 'draft' END);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS sequences_sync_status ON sequences;
CREATE TRIGGER sequences_sync_status
  BEFORE INSERT OR UPDATE ON sequences
  FOR EACH ROW EXECUTE FUNCTION sequences_sync_status();

-- Also expose user_id and team_id aliases needed by frontend SELECT
-- The sequences table only has account_id + created_by — we don't rebuild
-- the table here, but the view layer (bubs_compat_views) already covers this.
-- The SELECT in useSequences reads user_id/team_id — those come from the
-- raw table, which doesn't have them, so the select might return null.
-- Add them as generated columns pointing to account_id for compat.
ALTER TABLE sequences ADD COLUMN IF NOT EXISTS team_id uuid GENERATED ALWAYS AS (account_id) STORED;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.5: Shared set_rankora_account_id() BEFORE INSERT trigger
-- Adds to 17 legacy tables that have account_id NOT NULL with no default.
-- Pattern: IF NEW.account_id IS NULL THEN
--            NEW.account_id := COALESCE(NEW.team_id, get_primary_account(auth.uid()));
--          END IF;
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION set_rankora_account_id()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.account_id IS NULL THEN
    NEW.account_id := COALESCE(
      (CASE WHEN TG_TABLE_NAME IN ('guest_links','stage_tracker') THEN NULL
            ELSE NEW.account_id END),
      get_primary_account(auth.uid())
    );
  END IF;
  RETURN NEW;
END;
$$;

-- Simpler rewrite without the unused CASE:
CREATE OR REPLACE FUNCTION set_rankora_account_id()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.account_id IS NULL THEN
    NEW.account_id := get_primary_account(auth.uid());
  END IF;
  RETURN NEW;
END;
$$;

-- Apply to all 17 tables (DROP IF EXISTS + CREATE for idempotency)
DO $$ DECLARE
  tbl text;
BEGIN
  FOREACH tbl IN ARRAY ARRAY[
    'agency_clients',
    'agency_commissions',
    'agency_communications',
    'agency_contacts',
    'agency_invoices',
    'agency_mandates',
    'agency_placements',
    'guest_links',
    'hire_outcomes',
    'interviews',
    'outreach_history',
    'scorecard_responses',
    'scorecard_templates',
    'sequences',
    'stage_tracker',
    'talent_pool',
    'webhook_configs'
  ] LOOP
    -- Only if table has account_id column
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public'
        AND table_name   = tbl
        AND column_name  = 'account_id'
    ) THEN
      EXECUTE format(
        'DROP TRIGGER IF EXISTS trg_%I_account_id ON %I',
        tbl, tbl
      );
      EXECUTE format(
        'CREATE TRIGGER trg_%I_account_id BEFORE INSERT ON %I
           FOR EACH ROW EXECUTE FUNCTION set_rankora_account_id()',
        tbl, tbl
      );
    END IF;
  END LOOP;
END $$;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.6: outreach_log — add job_id column
-- ContactStrip.tsx inserts job_id into outreach_log
-- ────────────────────────────────────────────────────────────────────────────

ALTER TABLE outreach_log
  ADD COLUMN IF NOT EXISTS job_id uuid REFERENCES rankora_jobs(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_outreach_log_job_id ON outreach_log(job_id);


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.7: guest_links — add label column
-- GuestLinkDialog.tsx inserts label; used_at already exists from migration 0006
-- ────────────────────────────────────────────────────────────────────────────

ALTER TABLE guest_links
  ADD COLUMN IF NOT EXISTS label text;

-- Verify used_at exists (0006 added it); add if somehow missing
ALTER TABLE guest_links
  ADD COLUMN IF NOT EXISTS used_at timestamptz;

-- Also add account_id if missing (0017 adds it, but guest_links might have been
-- created after 0017 was applied — the DO block in 0017 is idempotent so this
-- is safe)
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'guest_links' AND column_name = 'account_id'
  ) THEN
    ALTER TABLE guest_links ADD COLUMN account_id uuid REFERENCES accounts(id);
    UPDATE guest_links SET account_id = (
      SELECT rj.account_id FROM rankora_jobs rj WHERE rj.id = guest_links.job_id
    ) WHERE account_id IS NULL;
  END IF;
END $$;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1.8: plans compat layer
-- PlansTab.tsx writes: dodo_product_id, dodo_credit_entitlement_id, price,
--   credits, active, is_trial, features
-- Base plans table has: price_cents, limits_json, status (no active column)
-- Option A: Add missing columns + BEFORE INSERT/UPDATE trigger to sync them
-- ────────────────────────────────────────────────────────────────────────────

-- Add compat columns to plans table
ALTER TABLE plans
  ADD COLUMN IF NOT EXISTS dodo_product_id text,
  ADD COLUMN IF NOT EXISTS dodo_credit_entitlement_id text,
  ADD COLUMN IF NOT EXISTS is_trial boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS price numeric,
  ADD COLUMN IF NOT EXISTS credits integer,
  ADD COLUMN IF NOT EXISTS active boolean,
  ADD COLUMN IF NOT EXISTS features jsonb;

-- Backfill active from status, price from price_cents, credits from limits_json
UPDATE plans SET
  active   = (status = 'active'),
  price    = (price_cents::numeric / 100.0),
  credits  = (limits_json->>'ai_credits_per_month')::int,
  features = limits_json
WHERE active IS NULL;

-- Trigger to keep price_cents/status/limits_json in sync with
-- price/active/credits/features when caller writes the compat columns
CREATE OR REPLACE FUNCTION plans_sync_compat_columns()
RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- Sync price → price_cents
  IF NEW.price IS NOT NULL THEN
    NEW.price_cents := round(NEW.price * 100)::integer;
  ELSIF NEW.price_cents IS NOT NULL AND NEW.price IS NULL THEN
    NEW.price := NEW.price_cents::numeric / 100.0;
  END IF;

  -- Sync active → status (and back)
  IF NEW.active IS NOT NULL THEN
    NEW.status := CASE WHEN NEW.active THEN 'active' ELSE 'archived' END;
  ELSIF NEW.status IS NOT NULL AND NEW.active IS NULL THEN
    NEW.active := (NEW.status = 'active');
  END IF;

  -- Sync credits → limits_json ai_credits_per_month
  IF NEW.credits IS NOT NULL THEN
    NEW.limits_json := COALESCE(NEW.limits_json, '{}'::jsonb)
      || jsonb_build_object('ai_credits_per_month', NEW.credits);
  END IF;

  -- Sync features → limits_json (merge in)
  IF NEW.features IS NOT NULL AND NEW.credits IS NULL THEN
    -- features column overrides limits_json entirely when no credits shortcut
    NEW.limits_json := NEW.features;
  END IF;

  -- Keep active in sync with status for SELECTs
  IF NEW.status IS NOT NULL THEN
    NEW.active := (NEW.status = 'active');
  END IF;

  -- Keep price in sync with price_cents for SELECTs
  IF NEW.price_cents IS NOT NULL THEN
    NEW.price := NEW.price_cents::numeric / 100.0;
  END IF;

  -- Keep credits in sync with limits_json for SELECTs
  NEW.credits := (COALESCE(NEW.limits_json, '{}'::jsonb)->>'ai_credits_per_month')::int;

  -- Ensure app_id is set
  IF NEW.app_id IS NULL THEN
    NEW.app_id := get_app_id('rankora');
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS plans_sync_compat_columns ON plans;
CREATE TRIGGER plans_sync_compat_columns
  BEFORE INSERT OR UPDATE ON plans
  FOR EACH ROW EXECUTE FUNCTION plans_sync_compat_columns();

-- Backfill again after trigger function exists (for existing rows)
UPDATE plans SET active = (status = 'active'), price = (price_cents::numeric / 100.0)
WHERE active IS NULL OR price IS NULL;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 2.8 (Realtime filter fix): Fix the tasks subscription
-- useTasks.tsx subscribes with filter: "team_id=eq.${teamId}"
-- The underlying rankora_tasks table has account_id, not team_id.
-- Since realtime WAL filters go against the base table, we need to
-- rebuild the tasks view to also expose the account_id as a REAL
-- persisted column name that realtime can filter on, OR we add a
-- team_id column to rankora_tasks.
-- Simplest fix: add team_id as a generated column on rankora_tasks.
-- ────────────────────────────────────────────────────────────────────────────

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name   = 'rankora_tasks'
      AND column_name  = 'team_id'
  ) THEN
    ALTER TABLE rankora_tasks
      ADD COLUMN team_id uuid GENERATED ALWAYS AS (account_id) STORED;
    CREATE INDEX IF NOT EXISTS idx_rankora_tasks_team_id ON rankora_tasks(team_id);
  END IF;
END $$;

-- Similarly, pipeline_stages realtime uses filter: "team_id=eq.${teamId}"
-- The underlying rankora_pipeline_stages table has account_id.
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name   = 'rankora_pipeline_stages'
      AND column_name  = 'team_id'
  ) THEN
    ALTER TABLE rankora_pipeline_stages
      ADD COLUMN team_id uuid GENERATED ALWAYS AS (account_id) STORED;
    CREATE INDEX IF NOT EXISTS idx_rankora_pipeline_stages_team_id ON rankora_pipeline_stages(team_id);
  END IF;
END $$;

