import { defineConfig, devices } from "@playwright/test";

/**
 * Playwright configuration for Rankora save-path smoke tests.
 * Targets the local dev server on port 8080.
 *
 * Required env vars for auth-gated flows:
 *   TEST_USER_EMAIL     – email of an existing test user
 *   TEST_USER_PASSWORD  – password for that user
 *   TEST_ADMIN_EMAIL    – email with admin role (for admin flows)
 *   TEST_ADMIN_PASSWORD – password for the admin user
 *
 * If these are not set, auth-gated tests are skipped automatically.
 */

const PORT = 8080;

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: false, // run sequentially to avoid auth state collisions
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  workers: 1,
  reporter: [["line"], ["html", { outputFolder: "playwright-report", open: "never" }]],

  use: {
    baseURL: `http://localhost:${PORT}`,
    trace: "on-first-retry",
    screenshot: "only-on-failure",
    video: "off",
    // Give the app time to hydrate on first load
    navigationTimeout: 15_000,
    actionTimeout: 10_000,
  },

  projects: [
    {
      name: "chromium",
      use: { ...devices["Desktop Chrome"] },
    },
  ],

  webServer: {
    command: "npm run dev",
    url: `http://localhost:${PORT}`,
    reuseExistingServer: true,
    timeout: 60_000,
    stdout: "ignore",
    stderr: "ignore",
  },
});

/**
 * e2e/save-paths.spec.ts
 *
 * Smoke-tests for the 20 critical save paths identified in the DB audit.
 * Each test:
 *   1. Signs in (skipped if TEST_USER_EMAIL / TEST_USER_PASSWORD not set)
 *   2. Performs the action
 *   3. Asserts no error toast appears (data-type="error" from Sonner)
 *   4. Asserts the expected UI element appears
 *
 * Run: npx playwright test e2e/save-paths.spec.ts --reporter=line
