import { test, expect, type Page } from "@playwright/test";

// ─── Credentials from env ─────────────────────────────────────────────────────
const USER_EMAIL = process.env.TEST_USER_EMAIL ?? "";
const USER_PASSWORD = process.env.TEST_USER_PASSWORD ?? "";
const ADMIN_EMAIL = process.env.TEST_ADMIN_EMAIL ?? USER_EMAIL;
const ADMIN_PASSWORD = process.env.TEST_ADMIN_PASSWORD ?? USER_PASSWORD;

const HAS_USER_CREDS = !!(USER_EMAIL && USER_PASSWORD);
const HAS_ADMIN_CREDS = !!(ADMIN_EMAIL && ADMIN_PASSWORD);

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Selector for Sonner error toasts */
const ERROR_TOAST = '[data-sonner-toast][data-type="error"]';
/** Selector for Sonner success toasts */
const SUCCESS_TOAST = '[data-sonner-toast][data-type="success"]';

async function signIn(page: Page, email: string, password: string) {
  await page.goto("/auth");
  await page.getByLabel(/email/i).first().fill(email);
  await page.getByLabel(/password/i).first().fill(password);
  await page.getByRole("button", { name: /sign in|log in/i }).first().click();
  // Wait for redirect away from /auth
  await page.waitForURL((url) => !url.pathname.startsWith("/auth"), {
    timeout: 15_000,
  });
}

async function signInAsUser(page: Page) {
  await signIn(page, USER_EMAIL, USER_PASSWORD);
}

async function signInAsAdmin(page: Page) {
  await signIn(page, ADMIN_EMAIL, ADMIN_PASSWORD);
}

/** Assert no error toast is visible */
async function assertNoErrorToast(page: Page) {
  // Allow up to 1.5 s for any error to appear before asserting clean
  await page.waitForTimeout(1_500);
  await expect(page.locator(ERROR_TOAST)).toHaveCount(0);
}

