// ─── Flow 10: Update profile ──────────────────────────────────────────────────
test("10. Update profile full_name — persists on refresh", async ({ page }) => {
  test.skip(!HAS_USER_CREDS, "No test user credentials in env");

  await signInAsUser(page);
  await page.goto("/profile");

  const nameInput = page
    .getByLabel(/full name|name/i)
    .or(page.locator('input[name="full_name"]'))
    .first();

  const current = await nameInput.inputValue().catch(() => "");
  const newName = `E2E User ${Date.now()}`;
  await nameInput.fill(newName);

  const saveBtn = page
    .getByRole("button", { name: /save|update/i })
    .first();
  await saveBtn.click();

  await assertNoErrorToast(page);
  await expect(page.locator(SUCCESS_TOAST).first()).toBeVisible({
    timeout: 8_000,
  });

  // Reload and verify persistence
  await page.reload();
  await page.waitForURL("/profile");
  const reloadedInput = page
    .getByLabel(/full name|name/i)
    .or(page.locator('input[name="full_name"]'))
    .first();
  await expect(reloadedInput).toHaveValue(newName);

  // Cleanup: restore original
  if (current) {
    await reloadedInput.fill(current);
    await page.getByRole("button", { name: /save|update/i }).first().click();
  }
});

